// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"valaciclovir":{"wirkmechanismus":"Hemmt die Vermehrung von Herpesviren in befallenen Zellen. Valaciclovir ist ein Prodrug (Valinester) von Aciclovir: Es wird im Darm viel besser aufgenommen und in Darm und Leber fast vollständig in Aciclovir umgewandelt, sodass drei- bis fünfmal höhere Aciclovir-Spiegel als nach Einnahme von Aciclovir selbst entstehen. In infizierten Zellen wird Aciclovir durch die virale Thymidinkinase zu Aciclovirtriphosphat aktiviert, das die virale DNA-Polymerase hemmt und zum Kettenabbruch führt. Latente Viren werden nicht beseitigt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Übelkeit, Erbrechen, Durchfall","Hautausschlag, auch durch Licht ausgelöst, Juckreiz"],"gelegentlich":["Leukopenie, Thrombozytopenie (vor allem bei geschwächter Abwehr)","Schwindel, Verwirrtheit, Halluzinationen, Bewusstseinstrübung, Zittern, Unruhe","Atemnot","Bauchbeschwerden","Erhöhte Leberwerte","Nesselsucht","Nierenschmerzen, Blut im Urin"],"selten":["Anaphylaxie (schwere allergische Reaktion), Angioödem","Ataxie, Sprechstörungen, Krampfanfälle, Enzephalopathie, Koma, Psychose, Delir","Nierenfunktionsstörung bis akutes Nierenversagen (besonders bei älteren Menschen oder zu hoher Dosis)"],"unbekannt":["DRESS (schwere Arzneimittelreaktion mit Eosinophilie und Organbeteiligung)"]},"schwangerschaft":"Schwangerschaftsregister zu Valaciclovir und Aciclovir zeigen kein erhöhtes Fehlbildungsrisiko; Anwendung nach ärztlicher Abwägung.","stillzeit":"Aciclovir geht in die Muttermilch über; die Mengen gelten als gering, Stillen ist nach ärztlicher Abwägung möglich.","hinweise":["Behandlung möglichst früh beginnen: bei Lippenherpes bei den ersten Anzeichen, bei Gürtelrose innerhalb von 72 Stunden nach Auftreten des Ausschlags.","Während der Behandlung ausreichend trinken, besonders ältere Menschen.","Genitalherpes bleibt ansteckend, auch unter Behandlung – Kondome verwenden.","Verwirrtheit oder Schwindel können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"valganciclovir":{"wirkmechanismus":"Hemmt die Vermehrung des Zytomegalievirus in befallenen Zellen. Valganciclovir ist ein Prodrug (Valinester) von Ganciclovir, das nach der Aufnahme im Darm und in der Leber rasch umgewandelt wird; so entstehen ähnliche Spiegel wie nach einer Ganciclovir-Infusion. In CMV-infizierten Zellen wird Ganciclovir durch die virale Kinase UL97 und danach durch zelluläre Enzyme zu Ganciclovirtriphosphat aktiviert, das die virale DNA-Polymerase hemmt. Weil es auch in teilungsaktive menschliche Zellen eingreift, schädigt es Knochenmark und Keimzellen.","nebenwirkungen":{"sehrHaeufig":["Neutropenie (Mangel an weissen Blutkörperchen), Anämie (Blutarmut)","Durchfall, Übelkeit, Erbrechen","Atemnot, Husten","Kopfschmerzen","Fieber, Müdigkeit","Candida-Infektion im Mund"],"haeufig":["Thrombozytopenie, Leukopenie, Panzytopenie","Infektionen (z. B. Blutvergiftung, Harnwegsinfekt, Grippe)","Appetitlosigkeit, Gewichtsverlust","Depression, Angst, Verwirrtheit, Schlaflosigkeit","Krampfanfälle, periphere Neuropathie, Schwindel, Kribbeln, Geschmacksstörungen","Netzhautablösung, Makulaödem, Augenschmerzen, Glaskörpertrübungen","Bauchschmerzen, Verstopfung, Verdauungsbeschwerden","Abweichende Leberwerte","Nierenfunktionsstörung, erhöhtes Kreatinin","Hautausschlag, Juckreiz, Nachtschweiss, Haarausfall","Muskel-, Gelenk- und Rückenschmerzen, Muskelkrämpfe"],"gelegentlich":["Knochenmarkversagen","Unruhe, Psychose, Halluzinationen","Zittern","Hörverlust","Herzrhythmusstörungen","Pankreatitis, Mundgeschwüre","Nierenversagen, Blut im Urin","Männliche Unfruchtbarkeit"],"selten":["Aplastische Anämie, Agranulozytose","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Nicht anwenden, ausser der Nutzen für die Mutter überwiegt eindeutig das Risiko für das Kind: Ganciclovir ist im Tierversuch fruchtschädigend und erbgutschädigend.","stillzeit":"Kontraindiziert – vor Beginn abstillen.","hinweise":["Tabletten mit einer Mahlzeit einnehmen; nicht zerbrechen oder zerkleinern und Hautkontakt mit beschädigten Tabletten oder der Lösung vermeiden (gründlich mit Wasser und Seife waschen).","Blutbild und Nierenwerte werden regelmässig kontrolliert; Fieber, Halsschmerzen, Blutungen oder blaue Flecken sofort melden.","Frauen verhüten während und 30 Tage nach der Behandlung, Männer verwenden während und 90 Tage nach der Behandlung Kondome.","Krampfanfälle, Schwindel und Verwirrtheit können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten","Pulver für Lösung zum Einnehmen"]},"valproinsaeure":{"wirkmechanismus":"Stabilisiert die Erregbarkeit von Nervenzellen und verhindert so verschiedene Anfallsformen. Valproinsäure erhöht die Konzentration des hemmenden Botenstoffs GABA im Gehirn (u. a. durch Hemmung des GABA-Abbaus) und blockiert spannungsabhängige Natrium- sowie T-Typ-Calciumkanäle. Sie wird in der Leber vor allem durch Glucuronidierung und Beta-Oxidation abgebaut und hemmt selbst mehrere Abbauwege anderer Arzneimittel (z. B. von Lamotrigin und Phenobarbital).","nebenwirkungen":{"sehrHaeufig":["Zittern (Tremor)","Übelkeit"],"haeufig":["Thrombozytopenie (Mangel an Blutplättchen), Anämie","Hyponatriämie (Natriummangel), Gewichtszunahme","Schläfrigkeit, Kopfschmerzen, Gedächtnisstörungen, extrapyramidale Bewegungsstörungen","Verwirrtheit, Aggression, Unruhe, Halluzinationen","Erbrechen, Durchfall, Bauchschmerzen, Zahnfleischveränderungen","Leberschädigung","Vorübergehender Haarausfall, Nagelveränderungen","Menstruationsbeschwerden, Hörverlust"],"gelegentlich":["Panzytopenie, Leukopenie","Pankreatitis (teils lebensbedrohlich)","Enzephalopathie, Koma, Parkinsonismus, Gangunsicherheit","Hyperandrogenismus (vermehrte Behaarung, Akne), Ausbleiben der Regel","Angioödem, Vaskulitis (Gefässentzündung)","Verminderte Knochendichte","Nierenversagen, Pleuraerguss"],"selten":["Knochenmarkversagen (aplastische Anämie, Agranulozytose)","Hyperammonämie (erhöhtes Ammoniak im Blut)","Schilddrüsenunterfunktion","Reversible Demenz, kognitive Störungen","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS","Lupus erythematodes, Rhabdomyolyse (Muskelzerfall)","Fanconi-Syndrom (Nierentubulusschaden), Bettnässen","Männliche Unfruchtbarkeit, polyzystische Eierstöcke"]},"schwangerschaft":"Hohes Risiko für schwere Fehlbildungen (etwa 10 %) und Entwicklungsstörungen (bis 30–40 %). Bei bipolarer Störung kontraindiziert; bei Epilepsie nur, wenn es keine Alternative gibt, und nur im Rahmen des Schwangerschaftsverhütungsprogramms. Nie eigenmächtig absetzen, sondern sofort ärztlich besprechen.","stillzeit":"Geht nur in geringer Menge in die Muttermilch über; Stillen ist nach ärztlicher Abwägung möglich, das Kind auf Blutungszeichen und Gelbsucht beobachten.","hinweise":["Mädchen und Frauen im gebärfähigen Alter benötigen eine sichere Verhütung und eine jährliche ärztliche Überprüfung der Behandlung (Schwangerschaftsverhütungsprogramm).","Leberwerte, Blutbild und Gerinnung vor Behandlungsbeginn und regelmässig kontrollieren; bei Müdigkeit, Erbrechen, Bauchschmerzen, Gelbsucht oder Anfallszunahme sofort ärztlich melden.","Nicht abrupt absetzen – Gefahr von Krampfanfällen.","Alkohol meiden; Vorsicht beim Autofahren."],"darreichung":["Magensaftresistente Tabletten","Retardtabletten","Retardgranulat","Lösung zum Einnehmen","Injektionslösung"]},"valsartan":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Wirkung des gefässverengenden Hormons Angiotensin II an seinem Rezeptor blockiert. Valsartan ist ein direkt wirksamer, selektiver Antagonist am AT1-Rezeptor: Die Gefässe weiten sich, die Aldosteronausschüttung sinkt, und die Niere scheidet mehr Salz und Wasser aus, was Herz und Gefässe entlastet. Valsartan wird kaum verstoffwechselt und überwiegend über die Galle ausgeschieden; da der Bradykinin-Abbau nicht beeinflusst wird, tritt Reizhusten selten auf.","nebenwirkungen":{"haeufig":["Schwindel, auch beim Aufstehen (vor allem bei Herzschwäche oder nach Herzinfarkt)","Hypotonie (tiefer Blutdruck), auch beim Aufstehen (vor allem bei Herzschwäche oder nach Herzinfarkt)","Nierenfunktionsstörung (vor allem bei Herzschwäche oder nach Herzinfarkt)"],"gelegentlich":["Drehschwindel (Vertigo)","Husten","Bauchschmerzen, Übelkeit, Durchfall","Müdigkeit, Schwäche","Kopfschmerzen, Synkope (Ohnmacht)","Hyperkaliämie (erhöhtes Kalium), Kreatininanstieg, akutes Nierenversagen","Verschlechterung einer Herzschwäche","Angioödem (Schwellung von Gesicht, Lippen, Zunge, Rachen)"],"unbekannt":["Neutropenie, Thrombozytopenie, Abfall des Hämoglobins","Überempfindlichkeitsreaktionen einschliesslich Serumkrankheit","Hyponatriämie (Natriummangel)","Vaskulitis (Gefässentzündung)","Erhöhte Leberwerte","Hautausschlag, Juckreiz, bullöse Dermatitis (Blasenbildung)","Muskelschmerzen"]},"schwangerschaft":"Kontraindiziert; besonders im 2. und 3. Drittel fruchtschädigend (Nierenschäden, Fruchtwassermangel, verzögerte Schädelverknöcherung). Bei Kinderwunsch oder festgestellter Schwangerschaft sofort ärztlich auf ein anderes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten zum Übergang in die Muttermilch fehlen; besser untersuchte Alternativen wählen.","hinweise":["Täglich etwa zur gleichen Zeit mit Wasser einnehmen, unabhängig von den Mahlzeiten.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel und Kaliumpräparate nur nach ärztlicher Rücksprache.","Zu Beginn kann Schwindel auftreten – Vorsicht beim Autofahren.","Bei starkem Durchfall, Erbrechen oder Flüssigkeitsmangel ärztlich klären, ob die Einnahme vorübergehend pausiert werden soll."],"darreichung":["Filmtabletten"]},"vamorolon":{"wirkmechanismus":"Wirkt entzündungshemmend und verlangsamt so den Muskelabbau bei Duchenne-Muskeldystrophie, ähnlich wie Kortison. Vamorolon bindet an den Glukokortikoidrezeptor und hemmt entzündungsfördernde Signalwege wie NF-kappa-B, aktiviert aber in geringerem Mass jene Gene, die für typische Kortison-Nebenwirkungen verantwortlich sind. Zusätzlich blockiert es den Mineralokortikoidrezeptor.","nebenwirkungen":{"sehrHaeufig":["Cushing-ähnliches Aussehen (z. B. rundes Gesicht)","Erbrechen","Gewichtszunahme","Reizbarkeit"],"haeufig":["Bauchschmerzen","Durchfall","Kopfschmerzen","Gesteigerter Appetit"],"unbekannt":["Nebenniereninsuffizienz nach Absetzen oder in Stresssituationen","Erhöhte Infektanfälligkeit","Verhaltensänderungen"]},"schwangerschaft":"Keine Erfahrungen; die Duchenne-Muskeldystrophie betrifft fast ausschliesslich Knaben. In der Schwangerschaft nicht empfohlen.","stillzeit":"Keine Daten; in der Stillzeit nicht empfohlen.","hinweise":["Einmal täglich mit der beiliegenden Dosierspritze genau nach ärztlicher Anweisung einnehmen.","Nicht eigenmächtig absetzen oder die Dosis senken – nur schrittweise nach ärztlicher Anweisung (Gefahr einer Nebennierenkrise).","Die Behandlung bei Operationen, Unfällen oder schweren Infekten immer angeben; Kontakt zu Windpocken oder Masern umgehend ärztlich melden."],"darreichung":["Suspension zum Einnehmen"]},"vancomycin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Vancomycin bindet an das D-Alanyl-D-Alanin-Ende der Zellwandbausteine und blockiert so deren Einbau ins Peptidoglykan. Es wirkt nur gegen grampositive Bakterien, auch gegen Methicillin-resistente Staphylokokken (MRSA) und Clostridioides difficile. Aus dem Darm wird es kaum aufgenommen: Eingenommen wirkt es deshalb nur im Darm, bei Infektionen im übrigen Körper muss es als Infusion gegeben werden.","nebenwirkungen":{"haeufig":["Rötung von Oberkörper und Gesicht bei der Infusion (Vancomycin-Infusionsreaktion), Blutdruckabfall","Atemnot, Stridor (pfeifendes Atemgeräusch)","Hautausschlag, Juckreiz, Nesselsucht, Schleimhautentzündung","Eingeschränkte Nierenfunktion (Anstieg von Kreatinin und Harnstoff)","Venenentzündung an der Infusionsstelle"],"gelegentlich":["Vorübergehender oder bleibender Hörverlust"],"selten":["Neutropenie, Agranulozytose, Thrombozytopenie, Eosinophilie","Anaphylaxie (schwere allergische Reaktion)","Tinnitus, Drehschwindel, Schwindel","Übelkeit","Interstitielle Nephritis, akutes Nierenversagen","Arzneimittelfieber, Schüttelfrost, Krämpfe der Brust- und Rückenmuskulatur","Vaskulitis (Gefässentzündung)"],"sehrSelten":["Pseudomembranöse Kolitis","Herzstillstand","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, exfoliative Dermatitis, lineare IgA-Dermatose)"],"unbekannt":["DRESS und akute generalisierte exanthematische Pustulose","Erbrechen, Durchfall","Akute Tubulusnekrose (Nierenschädigung)"]},"schwangerschaft":"Begrenzte Erfahrungen; als Infusion sind Nieren- und Gehörschäden beim Kind nicht ausgeschlossen. Nur bei klarer Notwendigkeit mit Spiegelkontrollen. Eingenommen gelangt kaum Wirkstoff ins Blut.","stillzeit":"Geht in die Muttermilch über. Als Infusion nur, wenn andere Antibiotika versagt haben; beim Säugling auf Durchfall und Pilzbefall achten.","hinweise":["Die Infusion wird langsam über mindestens 60 Minuten gegeben; Blutspiegel und Nierenwerte werden regelmässig kontrolliert.","Hörminderung, Ohrensausen oder Hautausschlag sofort melden.","Bei Clostridioides-difficile-Infektion das Mittel über die ganze verordnete Dauer einnehmen, auch wenn der Durchfall früher aufhört."],"darreichung":["Pulver zur Herstellung einer Infusionslösung (teils auch zur Herstellung einer Lösung zum Einnehmen)"]},"vandetanib":{"wirkmechanismus":"Hemmt Wachstumssignale von Schilddrüsenkrebszellen und die Bildung neuer Blutgefässe im Tumor. Vandetanib blockiert die Tyrosinkinasen RET, VEGFR-2 und den EGF-Rezeptor. Beim medullären Schilddrüsenkarzinom treibt häufig eine aktivierende RET-Mutation das Tumorwachstum an. Wegen der sehr langen Halbwertszeit (etwa 19 Tage) klingen Wirkungen und Nebenwirkungen nach dem Absetzen nur langsam ab.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Bauchschmerzen, Verdauungsbeschwerden","Hautausschlag, Akne, trockene Haut, Juckreiz, Nagelveränderungen","Lichtempfindlichkeit der Haut (Photosensibilisierung)","QT-Verlängerung im EKG","Bluthochdruck","Kopfschmerzen, Müdigkeit, Schwäche, Schlaflosigkeit, Depression","Hypokalzämie (Calciummangel), Appetitverlust","Infektionen der Atem- und Harnwege"],"haeufig":["Hypokaliämie, Hyponatriämie, Flüssigkeitsmangel","Hypothyreose (Schilddrüsenunterfunktion)","Hornhauttrübung, verschwommenes Sehen, trockene Augen","Hypertensive Krise, Durchblutungsstörungen des Gehirns","Nasenbluten, Bluthusten, Pneumonitis (Lungenentzündung ohne Erreger)","Mundtrockenheit, Stomatitis, Magen-Darm-Blutungen","Nierensteine, Nierenversagen, Eiweiss im Urin","Erhöhte Leberwerte, Gewichtsabnahme"],"gelegentlich":["Herzinsuffizienz, Kammerrhythmusstörungen, Herzstillstand","Krampfanfälle, Hirnödem","Pankreatitis, Darmdurchbruch, Darmverschluss","Atemversagen, Aspirationspneumonie","Blasenbildende Hautentzündung","Wundheilungsstörungen, Katarakt (grauer Star)"],"unbekannt":["Torsade de pointes und plötzlicher Herztod","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Aneurysmen und Gefässwandeinrisse (Dissektionen)"]},"schwangerschaft":"Nicht anwenden, ausser der Zustand erfordert es zwingend – kann das ungeborene Kind schädigen. Frauen müssen während der Behandlung und mindestens 4 Monate danach zuverlässig verhüten.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["EKG und Blutwerte (Kalium, Calcium, Magnesium, TSH) werden vor Beginn und regelmässig kontrolliert; Herzklopfen, Ohnmacht oder starken Schwindel sofort melden.","Wegen der sehr langen Halbwertszeit wirken Vandetanib und seine Nebenwirkungen nach dem Absetzen noch wochenlang nach.","Konsequenter Sonnenschutz (Kleidung, Sonnencreme) während und noch einige Zeit nach der Behandlung.","Vor jedem neuen Medikament, auch rezeptfreien, wegen der QT-Verlängerung Rücksprache halten."],"darreichung":["Filmtabletten"]},"vardenafil":{"wirkmechanismus":"Verbessert bei sexueller Erregung die Durchblutung des Penis und erleichtert so eine Erektion. Bei sexueller Stimulation wird in den Schwellkörpern Stickstoffmonoxid (NO) freigesetzt, das über den Botenstoff cGMP die glatte Muskulatur entspannt. Vardenafil hemmt selektiv die Phosphodiesterase 5 (PDE-5), die cGMP abbaut; dadurch bleibt cGMP länger erhalten, die Gefässe der Schwellkörper erweitern sich und es strömt mehr Blut ein. Ohne sexuelle Stimulation löst Vardenafil keine Erektion aus. Weil PDE-5 auch in Blutgefässen vorkommt, sinkt der Blutdruck leicht.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Gesichtsrötung (Flush)","Verstopfte Nase","Schwindel","Dyspepsie (Verdauungsbeschwerden)"],"gelegentlich":["Sehstörungen, verändertes Farbsehen, Augenrötung, Augenschmerzen","Herzklopfen, beschleunigter Puls","Übelkeit, Bauchschmerzen, Durchfall, Mundtrockenheit, Sodbrennen","Rücken- und Muskelschmerzen","Schläfrigkeit, Schlafstörungen, Kribbeln (Parästhesien)","Verstärkte, länger anhaltende oder schmerzhafte Erektionen","Allergisches Ödem und Angioödem (Schwellung von Gesicht, Lippen, Rachen)","Erhöhte Leberwerte"],"selten":["Priapismus (schmerzhafte Dauererektion über 4 Stunden – Notfall)","Herzinfarkt, Angina pectoris, ventrikuläre Herzrhythmusstörungen","Synkope (Ohnmacht), Blutdruckabfall, auch beim Aufstehen","Krampfanfälle, vorübergehender Gedächtnisverlust (Amnesie)","Erhöhter Augeninnendruck","Nasenbluten","Lichtempfindlichkeit der Haut","Brustschmerzen"],"unbekannt":["Nicht-arteriitische anteriore ischämische Optikusneuropathie (NAION) mit plötzlichem Sehverlust","Plötzliche Schwerhörigkeit oder Hörverlust","Blut im Urin oder im Sperma, Penisblutung"]},"schwangerschaft":"Nicht für Frauen bestimmt.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Etwa 25–60 Minuten vor dem Geschlechtsverkehr einnehmen, höchstens einmal täglich; eine fettreiche Mahlzeit kann den Wirkeintritt der Filmtabletten verzögern.","Schmelztablette auf der Zunge zergehen lassen, ohne Flüssigkeit; Schmelz- und Filmtabletten sind nicht gleichwertig dosiert und nicht austauschbar.","Bei einer Erektion über 4 Stunden oder bei plötzlichem Seh- oder Hörverlust sofort ärztliche Hilfe holen.","Bei Brustschmerzen keine Nitrate (z. B. Nitroglycerin-Spray) anwenden und das Notfallteam über die Vardenafil-Einnahme informieren."],"darreichung":["Filmtabletten","Schmelztabletten"]},"vareniclin":{"wirkmechanismus":"Erleichtert den Rauchstopp, indem es Entzugssymptome und Rauchverlangen mildert und zugleich die «Belohnung» durch eine Zigarette abschwächt. Vareniclin bindet als partieller Agonist mit hoher Affinität an den α4β2-Nikotinrezeptor im Gehirn: Es stimuliert ihn schwächer als Nikotin und bewirkt so eine mässige Dopaminfreisetzung, blockiert aber gleichzeitig die Bindung von Nikotin. Es wird kaum verstoffwechselt und grösstenteils unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Abnorme Träume, Schlaflosigkeit","Kopfschmerzen","Nasen-Rachen-Entzündung"],"haeufig":["Gewichtszunahme, Appetitveränderungen","Schläfrigkeit, Schwindel, Geschmacksstörungen","Erbrechen, Verstopfung, Durchfall, Blähungen, Bauchschmerzen, Sodbrennen","Mundtrockenheit, Zahnschmerzen","Atemnot, Husten","Hautausschlag, Juckreiz","Gelenk-, Muskel- und Rückenschmerzen","Brustschmerzen, Müdigkeit"],"gelegentlich":["Suizidgedanken, Depression, Angst, Panik, Aggressivität, Halluzinationen, Stimmungsschwankungen","Krampfanfälle, Zittern","Angina pectoris, Herzrasen, Herzklopfen","Bluthochdruck, Hitzewallungen","Ohrensausen, Bindehautentzündung","Vermehrtes Schwitzen, Akne"],"selten":["Psychose, Schlafwandeln, abnormes Verhalten","Schlaganfall","Vorhofflimmern","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, Erythema multiforme), Angioödem"],"unbekannt":["Vorübergehender Bewusstseinsverlust"]},"schwangerschaft":"Beobachtungsdaten zeigen kein erhöhtes Fehlbildungsrisiko; aus Vorsicht in der Schwangerschaft trotzdem nicht anwenden.","stillzeit":"Nicht bekannt, ob Vareniclin in die Muttermilch übergeht (im Tierversuch ja); nur nach ärztlicher Abwägung.","hinweise":["Ein Rauchstopp-Datum festlegen und 1–2 Wochen davor mit der Einnahme beginnen; die Behandlung dauert in der Regel 12 Wochen.","Nach dem Essen mit einem Glas Wasser einnehmen (weniger Übelkeit).","Bei Stimmungsveränderungen, Unruhe oder Suizidgedanken sofort absetzen und ärztliche Hilfe suchen.","Alkohol einschränken; Vorsicht beim Autofahren."],"darreichung":["Filmtabletten"]},"varicella-zoster-immunglobulin":{"wirkmechanismus":"Verleiht sofortigen, vorübergehenden Schutz gegen das Windpockenvirus (passive Immunisierung). Das Präparat enthält menschliche Immunglobuline (vor allem IgG) aus dem Plasma von Spendern mit hohem Antikörperspiegel gegen das Varicella-Zoster-Virus. Die Antikörper neutralisieren das Virus und können so eine Erkrankung verhindern oder abschwächen. Der Schutz hält einige Wochen an.","nebenwirkungen":{"unbekannt":["Grippeähnliche Reaktionen: Schüttelfrost, Fieber, Kopfschmerzen, Übelkeit, Erbrechen","Gelenk- und mässige Rückenschmerzen","Blutdruckabfall, selten plötzlicher Kreislaufkollaps","Allergische Reaktionen bis zum anaphylaktischen Schock","Aseptische Meningitis (nicht-infektiöse Hirnhautentzündung)","Hämolytische Anämie (Blutzerfall)","Anstieg des Kreatinins bis akutes Nierenversagen","Thromboembolien (Herzinfarkt, Schlaganfall, Lungenembolie, tiefe Venenthrombose)"]},"schwangerschaft":"Kann angewendet werden – Schwangere ohne Immunität gehören zu den wichtigsten Zielgruppen. Erfahrungen mit Immunglobulinen zeigen keine schädlichen Wirkungen auf das Ungeborene.","stillzeit":"Kann angewendet werden; Immunglobuline gehen in die Muttermilch über.","hinweise":["Möglichst rasch nach dem Kontakt verabreichen – je früher, desto besser die Schutzwirkung.","Infusion nur unter ärztlicher Überwachung; vorher ausreichend trinken.","Lebendimpfungen erst 3 Monate später; Antikörpertests können vorübergehend falsch positiv sein."],"darreichung":["Infusionslösung"]},"varizellen-impfstoff":{"wirkmechanismus":"Löst eine abgeschwächte, meist unbemerkte Infektion aus, nach der das Immunsystem vor Windpocken geschützt ist. Der Impfstoff enthält lebende, abgeschwächte Varizella-Zoster-Viren (Oka-Stamm). Sie regen die Bildung von Antikörpern und eine zelluläre Immunantwort an. Zwei Dosen verhindern Windpocken in den meisten Fällen; Durchbruchserkrankungen verlaufen meist mild.","nebenwirkungen":{"sehrHaeufig":["Schmerzen und Rötung an der Einstichstelle","Fieber"],"haeufig":["Schwellung und Juckreiz an der Einstichstelle","Hautausschlag, auch windpockenähnliche Bläschen","Reizbarkeit"],"gelegentlich":["Kopfschmerzen, Müdigkeit","Lymphknotenschwellung","Husten, Schnupfen","Übelkeit, Erbrechen","Gelenk- und Muskelschmerzen"],"selten":["Durchfall, Bauchschmerzen","Nesselsucht","Mittelohrentzündung, Bindehautentzündung"],"unbekannt":["Herpes zoster (Gürtelrose) durch das Impfvirus","Thrombozytopenie (Mangel an Blutplättchen)","Anaphylaxie (schwere allergische Reaktion)","Hirnentzündung (Enzephalitis), Kleinhirnentzündung, Schlaganfall","Fieberkrämpfe","Gefässentzündungen (z. B. Purpura Schönlein-Henoch)","Erythema multiforme (Hautreaktion)"]},"schwangerschaft":"Kontraindiziert. Eine Schwangerschaft soll bis 1 Monat nach der Impfung vermieden werden.","stillzeit":"Impfung ungeschützter stillender Frauen nach ärztlicher Abwägung möglich; eine Übertragung auf den Säugling wurde nicht beobachtet.","hinweise":["Zwei Dosen im Abstand von mindestens 4 Wochen; Kleinkinder erhalten die Impfung in der Schweiz meist kombiniert mit MMR.","Während 6 Wochen nach der Impfung keine Acetylsalicylsäure (z. B. Aspirin) geben – Gefahr des Reye-Syndroms.","Tritt nach der Impfung ein Bläschenausschlag auf, die Bläschen abdecken und Kontakt zu Schwangeren, Neugeborenen und Immungeschwächten meiden."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionssuspension"]},"vedolizumab":{"wirkmechanismus":"Verhindert, dass bestimmte Abwehrzellen aus dem Blut in die entzündete Darmwand einwandern. Vedolizumab ist ein humanisierter monoklonaler IgG1-Antikörper, der an das alpha4beta7-Integrin auf Gedächtnis-T-Lymphozyten bindet. Dadurch wird deren Anheftung an das Adhäsionsmolekül MAdCAM-1 blockiert, das vorwiegend in den Blutgefässen des Darms vorkommt. Die Wirkung ist weitgehend auf den Darm beschränkt; die allgemeine Immunabwehr wird kaum geschwächt.","nebenwirkungen":{"sehrHaeufig":["Nasen-Rachen-Entzündung (Erkältung)","Kopfschmerzen","Gelenkschmerzen"],"haeufig":["Bronchitis, Magen-Darm-Infekt, Grippe, Nasennebenhöhlen- und Rachenentzündung, Gürtelrose","Parästhesien (Kribbeln)","Bluthochdruck","Husten, Halsschmerzen","Übelkeit, Verdauungsbeschwerden, Verstopfung, Blähungen, Analabszess, Analfissur, Hämorrhoiden","Ausschlag, Juckreiz, Ekzem, Akne, Nachtschweiss","Rückenschmerzen, Muskelkrämpfe, Gliederschmerzen","Fieber, Müdigkeit; Reaktionen an der Einstichstelle (bei Spritze)"],"gelegentlich":["Infektionen der Atemwege, Scheidenpilz, Follikulitis","Verschwommenes Sehen","Infusionsreaktionen, Schüttelfrost"],"sehrSelten":["Lungenentzündung","Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Interstitielle Lungenerkrankung"]},"schwangerschaft":"Vorsichtshalber vermeiden, ausser der Nutzen überwiegt klar das Risiko; Frauen im gebärfähigen Alter verhüten während und bis 18 Wochen nach der letzten Gabe.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Stillen nur nach ärztlicher Abwägung.","hinweise":["Neue Verwirrtheit, Sehstörungen, Lähmungen oder Gangunsicherheit sofort ärztlich melden (PML).","Vor Beginn Impfstatus vervollständigen; bei Fieber oder Infektzeichen ärztlich abklären lassen.","Infusionen erfolgen unter Überwachung; Fertigspritzen im Kühlschrank lagern."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung","Injektionslösung (Fertigspritze, Fertigpen)"]},"velaglucerase-alfa":{"wirkmechanismus":"Ersetzt ein Enzym, das bei Morbus Gaucher fehlt, sodass sich ein Fettstoff nicht mehr in den Zellen ablagert. Velaglucerase alfa wird in einer menschlichen Zelllinie hergestellt und hat dieselbe Aminosäuresequenz wie die natürliche Glucocerebrosidase. Ihre mannosereichen Zuckerketten sorgen für die Aufnahme in Makrophagen (Fresszellen), wo sie in den Lysosomen das angehäufte Glucocerebrosid spaltet. Dadurch bessern sich Blutarmut und Plättchenmangel, und Milz und Leber werden kleiner.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen, Schwindel","Bauchschmerzen","Knochen-, Gelenk- und Rückenschmerzen","Infusionsbedingte Reaktionen","Schwäche, Müdigkeit, Fieber"],"haeufig":["Überempfindlichkeitsreaktionen, auch Anaphylaxie und allergische Hautentzündung","Herzrasen","Bluthochdruck, Blutdruckabfall, Hautrötung mit Hitzegefühl","Übelkeit","Hautausschlag, Nesselsucht","Verlängerte Gerinnungszeit (aPTT) im Labor","Bildung neutralisierender Antikörper"]},"schwangerschaft":"Begrenzte Erfahrungen. Eine Behandlung kann nach ärztlicher Abwägung fortgeführt werden; Schwangerschaft und Wochenbett eng überwachen.","stillzeit":"Keine Daten zum Übergang in die Muttermilch. Anwendung nach ärztlicher Abwägung.","hinweise":["Wird alle 2 Wochen als Infusion in eine Vene gegeben (rund 60 Minuten); nach Schulung ist eine Heiminfusion möglich.","Während und nach der Infusion auf Zeichen einer allergischen Reaktion achten und sie sofort melden.","Blutbild, Organgrösse und Antikörper werden regelmässig kontrolliert."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"velmanase-alfa":{"wirkmechanismus":"Ersetzt ein fehlendes Enzym, damit sich bestimmte Zuckerverbindungen nicht mehr in den Zellen anhäufen. Velmanase alfa ist eine gentechnisch hergestellte menschliche Alpha-Mannosidase. Sie wird über Mannose-6-Phosphat-Rezeptoren in die Zellen aufgenommen und spaltet in den Lysosomen mannosereiche Oligosaccharide. Dadurch sinken die Oligosaccharide im Blut; auf die Beteiligung des Nervensystems wirkt sie nicht.","nebenwirkungen":{"haeufig":["Infusionsbedingte Reaktionen und Überempfindlichkeitsreaktionen (z. B. Fieber, Schüttelfrost, Ausschlag, Nesselsucht, Erbrechen)","Durchfall, Übelkeit, Bauchschmerzen","Kopfschmerzen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen. Nur anwenden, wenn der Zustand der Frau eine Behandlung erfordert.","stillzeit":"Nicht bekannt, ob Velmanase alfa in die Muttermilch übergeht. Entscheid über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird wöchentlich als Infusion in eine Vene gegeben.","Fieber, Atemnot, Schwellungen oder Ausschlag während oder nach der Infusion sofort melden."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"vemurafenib":{"wirkmechanismus":"Hemmt ein krankhaft dauerhaft eingeschaltetes Wachstumssignal in Melanomzellen. Vemurafenib blockiert die mutierte Serin-Threonin-Kinase BRAF (v. a. V600E) und damit den MAPK-Signalweg (RAF-MEK-ERK); die Tumorzellen hören auf zu wachsen und sterben ab. In Zellen ohne BRAF-Mutation kann es den Signalweg paradoxerweise aktivieren – eine Erklärung für neue Hauttumoren. Die Kombination mit dem MEK-Hemmer Cobimetinib verstärkt die Wirkung und vermindert diese Hautnebenwirkungen.","nebenwirkungen":{"sehrHaeufig":["Gelenkschmerzen, Muskelschmerzen, Müdigkeit","Hautausschlag, Juckreiz, Lichtempfindlichkeit, Sonnenbrand","Plattenepithelkarzinom der Haut, Keratoakanthom, Hautpapillome, seborrhoische Keratose","Haarausfall, trockene Haut, Hyperkeratose (Hautverhornung), Hand-Fuss-Syndrom","Übelkeit, Erbrechen, Durchfall, Verstopfung","Appetitlosigkeit, Kopfschmerzen, Geschmacksstörung","Fieber, Wassereinlagerungen in den Beinen"],"haeufig":["Basalzellkarzinom (heller Hautkrebs), neues Melanom","QT-Verlängerung im EKG","Erhöhte Leberwerte","Gesichtsnervenlähmung (Fazialisparese)","Uveitis (Entzündung im Auge)","Pannikulitis, Erythema nodosum (Entzündung des Unterhautfettgewebes)","Arthritis, Follikulitis"],"gelegentlich":["Plattenepithelkarzinome ausserhalb der Haut (z. B. im Kopf-Hals-Bereich)","Netzhautvenenverschluss","Leberschädigung","Pankreatitis (Bauchspeicheldrüsenentzündung)"],"selten":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","DRESS (schwere Arzneimittelreaktion mit Hautausschlag und Organbeteiligung)"],"unbekannt":["Akute Nierenschädigung","Verstärkte Strahlenschäden (Radiation-Recall)","Fortschreiten bestehender Tumoren mit RAS-Mutation"]},"schwangerschaft":"Nicht anwenden, ausser der Nutzen überwiegt klar das Risiko. Frauen im gebärfähigen Alter müssen während und mindestens 6 Monate nach der Behandlung zuverlässig verhüten; hormonale Verhütungsmittel können weniger wirksam sein.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Zweimal täglich im Abstand von etwa 12 Stunden einnehmen; Tabletten ganz schlucken.","Sonne meiden, schützende Kleidung und Breitband-Sonnenschutz (UVA/UVB) sowie Lippenschutz verwenden.","Vor Beginn und regelmässig während der Behandlung Haut, Kopf-Hals-Bereich, EKG und Leberwerte kontrollieren lassen; neue Hautveränderungen melden."],"darreichung":["Filmtabletten"]},"venetoclax":{"wirkmechanismus":"Löst in Krebszellen das körpereigene Selbstzerstörungsprogramm wieder aus. Venetoclax hemmt selektiv das Eiweiss BCL-2, das in CLL- und AML-Zellen übermässig gebildet wird und den programmierten Zelltod (Apoptose) verhindert. Werden die gebundenen pro-apoptotischen Proteine freigesetzt, sterben die Krebszellen rasch ab – bei grosser Tumormasse so schnell, dass ein Tumorlysesyndrom entstehen kann.","nebenwirkungen":{"sehrHaeufig":["Neutropenie (Mangel an weissen Blutkörperchen), auch mit Fieber","Anämie, Thrombozytopenie","Infektionen der oberen Atemwege, Lungenentzündung","Durchfall, Übelkeit, Erbrechen, Verstopfung","Müdigkeit","Hyperphosphatämie (erhöhtes Phosphat)","Blutungen und Appetitlosigkeit (v. a. bei AML)"],"haeufig":["Tumorlysesyndrom","Sepsis (Blutvergiftung)","Harnwegsinfektion","Hyperkaliämie, Hyperurikämie, Hypokalzämie","Anstieg des Kreatinins","Lymphopenie","Bauchschmerzen, Gewichtsverlust","Gallenblasenentzündung, Gallensteine (bei AML)"]},"schwangerschaft":"Nicht anwenden. Frauen sollen während und bis mindestens 30 Tage nach der Behandlung sicher verhüten; hormonale Verhütung zusätzlich mit einer Barrieremethode absichern.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Ab 2 Tage vor Beginn und bei jeder Dosissteigerung täglich 1,5–2 Liter Wasser trinken (Schutz vor Tumorlyse).","Täglich zur gleichen Zeit mit einer Mahlzeit und Wasser einnehmen, ganz schlucken.","Grapefruit, Pomelos, Bitterorangen und Sternfrucht meiden.","Fieber, Schüttelfrost, Muskelkrämpfe, Herzstolpern oder wenig Urin sofort melden."],"darreichung":["Filmtabletten"]},"venlafaxin":{"wirkmechanismus":"Hellt die Stimmung auf und lindert Angst, indem es die Botenstoffe Serotonin und Noradrenalin im Gehirn länger wirken lässt. Venlafaxin und sein aktiver Hauptmetabolit O-Desmethylvenlafaxin (Desvenlafaxin, gebildet über CYP2D6) hemmen die Wiederaufnahme von Serotonin und – vor allem in höheren Dosen – von Noradrenalin; Dopamin wird nur schwach beeinflusst. An muskarinischen, histaminergen und adrenergen Rezeptoren wirkt es praktisch nicht.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Mundtrockenheit, Verstopfung","Kopfschmerzen, Schwindel","Schläfrigkeit, Schlaflosigkeit","Vermehrtes Schwitzen (auch nachts)"],"haeufig":["Appetitminderung, Gewichtsveränderungen","Nervosität, Unruhe, abnorme Träume, Verwirrtheit","Verminderte Libido, Orgasmus-, Ejakulations- und Erektionsstörungen","Zittern (Tremor), Akathisie (Bewegungsunruhe), Kribbeln","Sehstörungen, erweiterte Pupillen, Ohrensausen (Tinnitus)","Herzklopfen, Herzrasen, Blutdruckanstieg, Hitzewallungen","Durchfall, Erbrechen","Erschwertes oder häufiges Wasserlassen, erhöhtes Cholesterin"],"gelegentlich":["Manie, Hypomanie, Halluzinationen","Ohnmacht (Synkope), Blutdruckabfall beim Aufstehen","Magen-Darm-Blutungen, Blutergüsse","Lichtempfindlichkeit, Nesselsucht, Angioödem, Haarausfall","Harnverhalt","Erhöhte Leberwerte"],"selten":["Krampfanfälle","Serotoninsyndrom, malignes neuroleptisches Syndrom","QT-Verlängerung, Torsade de pointes, Kammerflimmern","Hyponatriämie (Natriummangel), SIADH","Agranulozytose, aplastische Anämie","Akutes Engwinkelglaukom","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse), Anaphylaxie","Pankreatitis, Hepatitis, Rhabdomyolyse"],"sehrSelten":["Tardive Dyskinesien (Spätdyskinesien)"],"unbekannt":["Suizidgedanken und suizidales Verhalten","Aggressivität","Stress-Kardiomyopathie (Takotsubo)","Thrombozytopenie"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme gegen Ende der Schwangerschaft sind beim Neugeborenen Anpassungsstörungen und Entzugssymptome möglich, ebenso ein erhöhtes Risiko für Nachblutungen bei der Mutter.","stillzeit":"Venlafaxin und O-Desmethylvenlafaxin gehen in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Retardkapseln einmal täglich zu einer Mahlzeit, immer etwa zur gleichen Zeit, unzerkaut schlucken.","Nicht abrupt absetzen, sondern über mehrere Wochen ausschleichen (Absetzsymptome wie Schwindel, Kribbeln, Übelkeit, Unruhe).","Blutdruck regelmässig kontrollieren.","Alkohol meiden; die Fahrtüchtigkeit kann beeinträchtigt sein."],"darreichung":["Retardkapseln"]},"verapamil":{"wirkmechanismus":"Verlangsamt den Herzschlag, senkt den Blutdruck und entlastet das Herz, indem es den Calcium-Einstrom in Herz- und Gefässmuskelzellen hemmt. Verapamil blockiert L-Typ-Calciumkanäle im Herzen und in den Gefässen: Es bremst die Erregungsbildung im Sinusknoten und die Überleitung im AV-Knoten (Antiarrhythmikum Klasse IV), vermindert die Kontraktionskraft und erweitert die Herzkranz- und peripheren Arterien. Verapamil wird über CYP3A4 abgebaut und hemmt selbst CYP3A4 und P-Glykoprotein, was viele Wechselwirkungen erklärt.","nebenwirkungen":{"haeufig":["Schwindel, Kopfschmerzen","Bradykardie (langsamer Puls)","Hypotonie (tiefer Blutdruck), Flush (Gesichtsrötung)","Verstopfung","Übelkeit","Periphere Ödeme (Wassereinlagerungen)"],"gelegentlich":["Herzklopfen, beschleunigter Puls","Bauchschmerzen","Müdigkeit"],"selten":["Kribbeln (Parästhesien), Zittern","Schläfrigkeit","Ohrensausen (Tinnitus)","Erbrechen","Vermehrtes Schwitzen"],"unbekannt":["AV-Block 1. bis 3. Grades, Sinusknotenstillstand, Asystolie (Herzstillstand)","Verschlechterung einer Herzschwäche","Überempfindlichkeitsreaktionen, Angioödem, Stevens-Johnson-Syndrom, Erythema multiforme","Zahnfleischwucherung (Gingivahyperplasie), Ileus (Darmverschluss)","Hyperkaliämie (erhöhtes Kalium), erhöhte Leberwerte","Muskel- und Gelenkschmerzen, Muskelschwäche, extrapyramidale Bewegungsstörungen","Brustvergrösserung beim Mann, Milchfluss (Galaktorrhö), Erektionsstörungen","Bronchospasmus, Atemnot"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung; Verapamil passiert die Plazenta, die Erfahrungen sind begrenzt.","stillzeit":"Verapamil geht in die Muttermilch über; nur anwenden, wenn es für die Mutter unbedingt nötig ist.","hinweise":["Retardtabletten nicht zerkauen oder zermörsern.","Alkohol meiden: Verapamil verstärkt und verlängert die Alkoholwirkung. Auch Grapefruitsaft meiden.","Puls regelmässig messen; bei Puls unter 50 pro Minute, Schwindel oder Ohnmacht ärztlich melden.","Kann die Fahrtüchtigkeit beeinträchtigen, besonders zu Beginn und zusammen mit Alkohol."],"darreichung":["Filmtabletten","Retardtabletten","Injektionslösung (Spital)"]},"vericiguat":{"wirkmechanismus":"Verstärkt einen körpereigenen Signalweg, der die Blutgefässe erweitert und den Herzmuskel entlastet. Vericiguat stimuliert die lösliche Guanylatcyclase (sGC) direkt – unabhängig von Stickstoffmonoxid (NO) – und macht das Enzym zugleich empfindlicher für körpereigenes NO. Bei Herzinsuffizienz ist dieser NO-sGC-cGMP-Signalweg gestört; der Anstieg von cGMP entspannt die glatte Gefässmuskulatur und wirkt krankhaften Umbauprozessen am Herzmuskel entgegen.","nebenwirkungen":{"sehrHaeufig":["Hypotonie (tiefer Blutdruck)"],"haeufig":["Anämie (Blutarmut)","Schwindel","Kopfschmerzen","Übelkeit, Erbrechen","Dyspepsie (Verdauungsbeschwerden)","Gastroösophagealer Reflux (Sodbrennen)"]},"schwangerschaft":"Darf nicht angewendet werden – im Tierversuch fruchtschädigend. Frauen im gebärfähigen Alter müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Nicht stillen – ein Übergang in die Muttermilch ist nicht auszuschliessen.","hinweise":["Mit einer Mahlzeit einnehmen; bei Schluckbeschwerden kann die Tablette zerstossen und mit Wasser eingenommen werden.","Die Dosis wird je nach Blutdruck schrittweise gesteigert – Blutdruck regelmässig kontrollieren.","Keine Potenzmittel (PDE-5-Hemmer) ohne ärztliche Rücksprache einnehmen."],"darreichung":["Filmtabletten"]},"vigabatrin":{"wirkmechanismus":"Erhöht im Gehirn die Menge des beruhigenden Botenstoffs GABA. Vigabatrin hemmt irreversibel das Enzym GABA-Transaminase, das GABA abbaut; dadurch steigt die GABA-Konzentration im Gehirn und die Erregbarkeit der Nervenzellen sinkt. Weil das Enzym erst neu gebildet werden muss, hält die Wirkung länger an, als die kurze Halbwertszeit vermuten lässt.","nebenwirkungen":{"sehrHaeufig":["Gesichtsfeldeinschränkung (oft bleibend)","Schläfrigkeit, Müdigkeit","Gelenkschmerzen","Erregung und Unruhe bei Kindern"],"haeufig":["Blutarmut (Anämie)","Reizbarkeit, Nervosität, Aggressivität, Depression, Schlafstörungen","Kopfschmerzen, Schwindel, Kribbeln (Parästhesien), Zittern","Konzentrations- und Gedächtnisstörungen","Verschwommenes Sehen, Doppelbilder, Nystagmus (Augenzittern)","Übelkeit, Erbrechen, Bauchschmerzen","Gewichtszunahme, Ödeme (Wassereinlagerungen)","Haarausfall, Hautausschlag"],"gelegentlich":["Psychosen, Manie","Gangunsicherheit (Ataxie)"],"selten":["Suizidversuch","Enzephalopathie (Bewusstseinsstörung, Verwirrtheit)","Netzhauterkrankung","Angioödem (Schwellung von Haut und Schleimhäuten), Nesselsucht"],"sehrSelten":["Halluzinationen","Sehnerventzündung, Schwund des Sehnervs","Hepatitis (Leberentzündung)"],"unbekannt":["Bewegungsstörungen und MRT-Veränderungen im Gehirn bei Säuglingen","Verminderte Sehschärfe"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach sorgfältiger ärztlicher Abwägung; eine wirksame Behandlung nicht eigenmächtig absetzen.","stillzeit":"Vigabatrin geht in die Muttermilch über; vom Stillen wird abgeraten.","hinweise":["Gesichtsfeld vor Beginn und regelmässig während der Behandlung augenärztlich kontrollieren lassen; Sehveränderungen sofort melden.","Bringt die Behandlung keinen klaren Nutzen, wird sie schrittweise beendet.","Nicht abrupt absetzen, sondern über mehrere Wochen ausschleichen.","Kann Reaktionsvermögen und Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten","Granulat zur Herstellung einer Lösung zum Einnehmen"]},"vilanterol-fluticasonfuroat":{"wirkmechanismus":"Verbindet eine entzündungshemmende mit einer 24 Stunden anhaltenden bronchienerweiternden Wirkung, sodass eine Inhalation pro Tag genügt. Fluticasonfuroat ist ein stark wirksames Glukokortikoid mit langer Verweildauer in der Lunge und dämpft die Entzündung der Bronchialschleimhaut. Vilanterol stimuliert selektiv Beta-2-Rezeptoren der Bronchialmuskulatur und erweitert die Atemwege. Beide Wirkstoffe werden in der Leber über CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Nasen-Rachen-Entzündung (Nasopharyngitis)"],"haeufig":["Lungenentzündung (vor allem bei COPD)","Infektionen der oberen Atemwege, Bronchitis, Grippe, Nebenhöhlenentzündung","Pilzinfektion in Mund und Rachen (Soor)","Rachenschmerzen, Husten, Heiserkeit","Bauchschmerzen","Gelenk- und Rückenschmerzen, Muskelkrämpfe","Knochenbrüche","Fieber"],"gelegentlich":["Hyperglykämie (erhöhter Blutzucker)","Extrasystolen (Extraschläge des Herzens)","Verschwommenes Sehen"],"selten":["Überempfindlichkeitsreaktionen bis Anaphylaxie, Angioödem, Ausschlag, Nesselsucht","Angst, Zittern","Herzklopfen, beschleunigter Puls","Paradoxer Bronchospasmus"]},"schwangerschaft":"Nur nach ärztlicher Abwägung, wenn der Nutzen für die Mutter das mögliche Risiko für das Kind überwiegt; ein gut kontrolliertes Asthma ist wichtig.","stillzeit":"Nur nach ärztlicher Abwägung; ob die Wirkstoffe in die Muttermilch übergehen, ist nicht ausreichend bekannt.","hinweise":["Einmal täglich jeweils zur gleichen Tageszeit inhalieren; nicht zur Behandlung akuter Atemnot.","Nach der Inhalation den Mund mit Wasser ausspülen und ausspucken.","Nicht abrupt absetzen; eine Ritonavir- oder Cobicistat-haltige HIV-Therapie ärztlich angeben."],"darreichung":["Pulverinhalator"]},"vildagliptin":{"wirkmechanismus":"Verstärkt die Wirkung körpereigener Darmhormone, die nach dem Essen die Insulinausschüttung anregen. Vildagliptin hemmt das Enzym Dipeptidylpeptidase-4 (DPP-4), sodass die Inkretine GLP-1 und GIP langsamer abgebaut werden. Dadurch steigt die blutzuckerabhängige Insulinfreisetzung und die Glukagonausschüttung sinkt; bei normalem Blutzucker lässt die Wirkung nach. Vildagliptin wird hauptsächlich durch Hydrolyse und nicht über Cytochrom-P450-Enzyme abgebaut und über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Schwindel","Hypoglykämie (Unterzuckerung), vor allem in Kombination mit Sulfonylharnstoff oder Insulin","Kopfschmerzen und Zittern (in Kombination mit Metformin oder Sulfonylharnstoff)","Übelkeit (in Kombination mit Metformin)","Periphere Ödeme (Wassereinlagerungen) und Gewichtszunahme in Kombination mit Pioglitazon","Schwäche (Asthenie) in Kombination mit Sulfonylharnstoff"],"gelegentlich":["Verstopfung","Gelenkschmerzen (Arthralgie)"],"selten":["Angioödem (Schwellung von Gesicht, Lippen oder Rachen), häufiger zusammen mit ACE-Hemmern"],"sehrSelten":["Infektionen der oberen Atemwege, Nasen-Rachen-Entzündung"],"unbekannt":["Leberfunktionsstörungen bis Hepatitis (nach Absetzen meist rückläufig)","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Nesselsucht, schuppende und blasenbildende Hautveränderungen einschliesslich bullöses Pemphigoid","Kutane Vaskulitis","Muskelschmerzen (Myalgie)"]},"schwangerschaft":"Nicht anwenden: Es liegen keine ausreichenden Erfahrungen vor; in der Schwangerschaft wird Insulin bevorzugt.","stillzeit":"Nicht anwenden: Es ist nicht bekannt, ob Vildagliptin beim Menschen in die Muttermilch übergeht (bei Tieren ja).","hinweise":["Unabhängig von den Mahlzeiten einnehmen.","Leberwerte vor Beginn und im ersten Jahr alle 3 Monate kontrollieren lassen; bei Gelbfärbung von Haut oder Augen sofort ärztlich abklären.","Bei anhaltenden, starken Bauchschmerzen sofort ärztlich abklären lassen (mögliche Bauchspeicheldrüsenentzündung).","In Kombination mit Sulfonylharnstoff oder Insulin kann eine Unterzuckerung die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Tabletten"]},"vinblastin":{"wirkmechanismus":"Hemmt die Zellteilung von Krebszellen. Vinblastin bindet an Tubulin, den Baustein der Mikrotubuli, und verhindert deren Aufbau. Ohne funktionierenden Spindelapparat bleiben die Zellen in der Metaphase der Mitose stehen und sterben ab.","nebenwirkungen":{"sehrHaeufig":["Leukopenie (Mangel an weissen Blutkörperchen)"],"unbekannt":["Thrombozytopenie, Anämie","Haarausfall","Übelkeit, Erbrechen, Verstopfung bis Darmlähmung (paralytischer Ileus), Mundschleimhautentzündung","Nervenschäden (Kribbeln, Taubheit, Reflexverlust), Krampfanfälle","Knochen-, Kiefer- und Tumorschmerzen","Akute Atemnot, Bronchospasmus","Bluthochdruck, Herzinfarkt, Schlaganfall, Raynaud-Phänomen","SIADH (vermehrte ADH-Ausschüttung) mit Hyponatriämie; schwere Gewebeschäden bei Paravasat"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit; Vinblastin kann das Ungeborene schädigen. Frauen und Männer müssen während der Behandlung und einige Monate danach zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird ausschliesslich in die Vene gegeben; Schmerzen oder Brennen an der Infusionsstelle sofort melden.","Verstopfung vorbeugen: viel trinken, ballaststoffreich essen, nötigenfalls Abführmittel nach ärztlicher Anweisung.","Blutbild vor jeder Gabe kontrollieren; Fieber oder Infektzeichen sofort melden."],"darreichung":["Injektionslösung"]},"vincristin":{"wirkmechanismus":"Hemmt die Zellteilung von Krebszellen. Vincristin bindet an Tubulin, den Baustein der Mikrotubuli, und verhindert deren Aufbau. Ohne funktionierenden Spindelapparat bleiben die Zellen in der Metaphase der Mitose stehen und sterben ab. Da Mikrotubuli auch für die Nervenleitung wichtig sind, stehen Nervenschäden im Vordergrund der Nebenwirkungen, während das Knochenmark kaum gehemmt wird.","nebenwirkungen":{"sehrHaeufig":["Nervenschäden (Kribbeln, Taubheitsgefühl, Abschwächung der Reflexe, Muskelschwäche)","Haarausfall","Verstopfung"],"unbekannt":["Darmlähmung (paralytischer Ileus), Bauchkrämpfe","Kiefer-, Knochen- und Muskelschmerzen","Lähmungen von Hirnnerven (z. B. Heiserkeit, hängendes Augenlid, Doppelbilder), Hörverlust","Harnverhalt, Blutdruckschwankungen","Krampfanfälle, Sehstörungen bis zur vorübergehenden Erblindung","SIADH mit Hyponatriämie (Natriummangel)","Leichte Knochenmarkhemmung","Akute Atemnot, Bronchospasmus; schwere Gewebeschäden bei Paravasat"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit; Vincristin kann das Ungeborene schädigen. Frauen und Männer müssen während der Behandlung und einige Monate danach zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird ausschliesslich in die Vene gegeben (Gabe in den Rückenmarkskanal ist tödlich); bei Erwachsenen beträgt die Einzeldosis in der Regel höchstens 2 mg.","Verstopfung vorbeugen: viel trinken, ballaststoffreich essen, vorbeugend Abführmittel nach ärztlicher Anweisung.","Kribbeln, Taubheit, Gangunsicherheit, Kieferschmerzen oder Bauchkrämpfe dem Behandlungsteam melden."],"darreichung":["Injektionslösung"]},"vinflunin":{"wirkmechanismus":"Hemmt die Zellteilung von Krebszellen. Vinflunin ist ein fluoriertes Vinca-Alkaloid, das an Tubulin bindet und den Aufbau der Mikrotubuli hemmt. Dadurch wird der Spindelapparat gestört, die Zellen bleiben in der Mitose stehen und sterben durch Apoptose ab.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Leukopenie, Anämie, Thrombozytopenie","Appetitlosigkeit, Gewichtsabnahme","Periphere sensorische Neuropathie (Kribbeln, Taubheitsgefühl)","Verstopfung, Bauchschmerzen, Übelkeit, Erbrechen, Durchfall","Mundschleimhautentzündung","Haarausfall","Muskelschmerzen","Müdigkeit, Schwäche, Fieber, Reaktionen an der Infusionsstelle"],"haeufig":["Infektionen, febrile Neutropenie","Flüssigkeitsmangel (Dehydratation)","Kopfschmerzen, Schwindel, Geschmacksstörungen, Schlaflosigkeit","Darmverschluss (Ileus)","Herzrasen, Bluthochdruck, Venenthrombose, Venenentzündung","Atemnot, Husten","Kiefer-, Knochen-, Gelenk- und Rückenschmerzen","Hautausschlag, Juckreiz, Nesselsucht"],"unbekannt":["Myokardischämie (Durchblutungsstörung des Herzens), Herzinfarkt","QT-Verlängerung","Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Hyponatriämie, SIADH (vermehrte ADH-Ausschüttung)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit; im Tierversuch fruchtschädigend. Frauen und Männer müssen während der Behandlung und mehrere Monate danach zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Ab dem Tag der Infusion während mehrerer Tage vorbeugend Abführmittel einnehmen, viel trinken und ballaststoffreich essen.","Grapefruit und Grapefruitsaft meiden.","Blutbild vor jeder Infusion; Fieber oder starke Bauchschmerzen sofort melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"vinorelbin":{"wirkmechanismus":"Hemmt die Teilung von Krebszellen, indem es den Aufbau des Zellteilungsapparats stört. Vinorelbin ist ein halbsynthetisches Vinca-Alkaloid, das an Tubulin bindet und die Polymerisation der Mikrotubuli hemmt. Dadurch kann sich die Mitosespindel nicht ausbilden; die Zellen werden in der Metaphase (G2/M-Phase) blockiert und sterben ab. Die Wirkung auf die Mikrotubuli der Nervenzellen erklärt die Nervenschäden.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung: Neutropenie (Mangel an weissen Blutkörperchen) und Anämie (Blutarmut)","Neurologische Störungen, v. a. abgeschwächte Sehnenreflexe","Übelkeit und Erbrechen","Obstipation (Verstopfung)","Stomatitis (Mundschleimhautentzündung)","Haarausfall","Erhöhte Leberwerte","Reaktionen an der Injektionsstelle (Rötung, Schmerz, Venenentzündung)"],"haeufig":["Infektionen (bakteriell, viral oder durch Pilze)","Thrombozytopenie (Mangel an Blutplättchen)","Durchfall","Gelenk- und Muskelschmerzen, auch Kieferschmerzen","Erschöpfung (Asthenie), Fieber","Schmerzen, auch im Brustkorb und im Tumorbereich"],"gelegentlich":["Sepsis (Blutvergiftung)","Schwere Parästhesien (Kribbeln, Taubheit) und Muskelschwäche","Atemnot und Bronchospasmus (Verkrampfung der Atemwege)","Blutdruckabfall oder -anstieg, Hitzegefühl"],"selten":["Darmlähmung (paralytischer Ileus)","Herzinfarkt, Angina pectoris","Interstitielle Lungenerkrankung","Pankreatitis (Bauchspeicheldrüsenentzündung)","Gewebsnekrose bei Austritt der Infusion ins Gewebe (Paravasat)"],"sehrSelten":["Guillain-Barré-Syndrom (aufsteigende Lähmung)"],"unbekannt":["Febrile Neutropenie, septischer Schock","Hyponatriämie (Natriummangel) durch SIADH","Anaphylaxie, anaphylaktischer Schock (schwere allergische Reaktionen)"]},"schwangerschaft":"Im Tierversuch fruchtschädigend; in der Schwangerschaft nur bei zwingender Indikation. Frauen und Männer müssen während und noch mehrere Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – vor Behandlungsbeginn abstillen.","hinweise":["Die Infusion darf nur in die Vene gegeben werden – eine Gabe in den Rückenmarkskanal (intrathekal) ist tödlich.","Vor jeder Gabe wird das Blutbild kontrolliert; bei Fieber, Schüttelfrost oder Halsschmerzen sofort ärztliche Hilfe holen.","Kapseln unzerkaut mit Wasser zu einer leichten Mahlzeit schlucken, nicht lutschen; beschädigte Kapseln nicht berühren (reizend).","Verstopfung vorbeugen (Flüssigkeit, Abführmittel nach Rücksprache); bei Bauchschmerzen ohne Stuhlgang Arzt informieren."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Weichkapseln"]},"vismodegib":{"wirkmechanismus":"Blockiert einen Wachstumssignalweg (Hedgehog-Signalweg), der beim Basalzellkarzinom fast immer dauerhaft eingeschaltet ist. Vismodegib bindet an das Membranprotein Smoothened (SMO) und verhindert so die Aktivierung der GLI-Transkriptionsfaktoren, die Zellteilung und Tumorwachstum antreiben. Weil der Hedgehog-Signalweg auch für die Entwicklung des Embryos entscheidend ist, wirkt Vismodegib stark fruchtschädigend.","nebenwirkungen":{"sehrHaeufig":["Muskelkrämpfe","Haarausfall","Geschmacksstörungen bis Geschmacksverlust","Gewichtsverlust, Appetitlosigkeit","Müdigkeit","Übelkeit, Durchfall, Verstopfung","Gelenkschmerzen","Ausbleiben der Regelblutung (Amenorrhö)"],"haeufig":["Erhöhte Leberwerte","Flüssigkeitsmangel (Dehydratation), Hyponatriämie (Natriummangel)","Bauchschmerzen, Verdauungsbeschwerden","Muskel- und Rückenschmerzen","Erhöhte Kreatinkinase (Muskelenzym)","Verlust von Wimpern und Augenbrauen"],"unbekannt":["Medikamentenbedingte Leberschädigung","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Vorzeitiger Verschluss der Wachstumsfugen und vorzeitige Pubertät bei Kindern"]},"schwangerschaft":"Kontraindiziert – kann zum Tod des Embryos oder zu schweren Fehlbildungen führen. Frauen im gebärfähigen Alter verwenden zwei Verhütungsmethoden während und bis 24 Monate nach der letzten Dosis; Männer verwenden Kondome bis 2 Monate danach.","stillzeit":"Kontraindiziert, während der Behandlung und bis 24 Monate nach der letzten Dosis.","hinweise":["Schwangerschaftsverhütungsprogramm streng befolgen; Kapseln nie an andere Personen weitergeben.","Kein Blut spenden während und bis 24 Monate nach der Behandlung; Männer keine Samenspende bis 2 Monate danach.","Kapseln ganz schlucken, nicht öffnen oder zerdrücken.","Muskelkrämpfe und Geschmacksstörungen sind sehr häufig; belastende Beschwerden ärztlich besprechen."],"darreichung":["Hartkapseln"]},"vitamin-b-komplex":{"wirkmechanismus":"Ersetzt B-Vitamine, die als Hilfsstoffe von Enzymen für Energiestoffwechsel, Nerven und Blutbildung nötig sind. Thiamin (B1) wirkt als Thiaminpyrophosphat im Kohlenhydratstoffwechsel, Pyridoxin (B6) als Pyridoxalphosphat im Aminosäure- und Botenstoffwechsel der Nerven, Cyanocobalamin (B12) bei der DNA-Bildung, der Blutbildung und dem Aufbau der Nervenscheiden (Myelin). Breite Komplex-Präparate enthalten zusätzlich Riboflavin (B2), Nicotinamid, Pantothensäure und teils Biotin. Ein Nutzen bei Nervenbeschwerden ist vor allem bei tatsächlichem Mangel zu erwarten.","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz, Nesselsucht) bis zum anaphylaktischen Schock, vor allem nach Injektion"],"unbekannt":["Magen-Darm-Beschwerden (Übelkeit, Bauchschmerzen, Durchfall)","Harmlose intensive Gelbfärbung des Urins (Vitamin B2)","Akneartige Hautveränderungen (Vitamin B12)","Periphere Nervenschäden (sensorische Neuropathie) bei langdauernder Einnahme hoher Vitamin-B6-Dosen"]},"schwangerschaft":"In Dosen zur Bedarfsdeckung erlaubt; hoch dosierte Präparate (vor allem mit viel Vitamin B6) nur nach ärztlicher Abwägung.","stillzeit":"In üblichen Dosen erlaubt; sehr hohe Vitamin-B6-Dosen können die Milchbildung hemmen.","hinweise":["Hoch dosierte B6-haltige Präparate nicht über längere Zeit ohne ärztliche Kontrolle einnehmen.","Die intensive Gelbfärbung des Urins ist harmlos.","Vor Blutuntersuchungen die Einnahme biotinhaltiger Präparate angeben."],"darreichung":["Dragées","Filmtabletten","Injektionslösung"]},"voclosporin":{"wirkmechanismus":"Dämpft die Abwehrzellen, die bei Lupus die Nieren angreifen, und stabilisiert zusätzlich die Filterzellen der Niere. Voclosporin ist ein dem Ciclosporin verwandter Calcineurin-Hemmer: Es hemmt das Enzym Calcineurin und damit die Aktivierung von T-Lymphozyten und die Bildung von Interleukin-2. Zudem stabilisiert es das Zellgerüst der Podozyten (Deckzellen der Nierenkörperchen) und vermindert so die Eiweissausscheidung im Urin.","nebenwirkungen":{"sehrHaeufig":["Abnahme der Nierenfunktion (glomeruläre Filtrationsrate)","Bluthochdruck","Durchfall","Kopfschmerzen","Anämie (Blutarmut)","Husten"],"haeufig":["Harnwegs- und Atemwegsinfekte","Oberbauchschmerzen, Verdauungsbeschwerden","Haarausfall","Akutes Nierenversagen","Zittern (Tremor)","Hyperkaliämie (erhöhtes Kalium)","Appetitlosigkeit","Gürtelrose (Herpes zoster)"],"unbekannt":["PRES (posteriores reversibles Enzephalopathie-Syndrom)","Lymphome und andere bösartige Erkrankungen","Opportunistische Infektionen (z. B. PML, BK-Virus-Nephropathie)"]},"schwangerschaft":"Nicht empfohlen (keine ausreichenden Daten). Das gleichzeitig eingenommene Mycophenolat ist in der Schwangerschaft kontraindiziert – zuverlässige Verhütung ist nötig.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Zweimal täglich möglichst im Abstand von 12 Stunden auf nüchternen Magen einnehmen; Grapefruit meiden.","Nierenfunktion (eGFR), Blutdruck und Kalium werden regelmässig kontrolliert.","Sonnenschutz und regelmässige Hautkontrollen (Hautkrebsrisiko).","Vor jedem neuen Medikament, auch Antibiotika oder Pilzmitteln, auf die Einnahme hinweisen (viele Wechselwirkungen)."],"darreichung":["Weichkapseln"]},"vollelektrolytloesung-ringer-lactat-acetat":{"wirkmechanismus":"Ersetzt Wasser und Salze im Raum ausserhalb der Zellen. Die Lösung enthält Natrium, Kalium, Calcium, Chlorid (je nach Präparat auch Magnesium) in plasmaähnlicher Konzentration sowie Lactat, Acetat oder Malat. Diese organischen Anionen werden in Leber und Muskeln zu Bicarbonat umgewandelt und puffern Säuren; dadurch tritt im Gegensatz zu reiner Kochsalzlösung kaum eine hyperchlorämische Übersäuerung auf. Die Lösung verteilt sich im ganzen Extrazellulärraum, nur ein Teil bleibt in den Blutgefässen.","nebenwirkungen":{"unbekannt":["Überwässerung, Ödeme, Lungenödem, Verschlechterung einer Herzschwäche","Elektrolytstörungen (z. B. Hyperkaliämie, Hyponatriämie)","Metabolische Alkalose bei grossen Mengen","Reaktionen an der Infusionsstelle (Schmerzen, Venenreizung, Venenentzündung)","Überempfindlichkeitsreaktionen (Nesselsucht, Juckreiz), selten Anaphylaxie","Fieber"]},"schwangerschaft":"Kann angewendet werden; Vorsicht bei Präeklampsie und bei gleichzeitiger Gabe von Oxytocin (Gefahr der Hyponatriämie).","stillzeit":"Kann angewendet werden.","hinweise":["Wird unter Kontrolle von Elektrolyten, Säure-Basen-Haushalt und Flüssigkeitsbilanz gegeben.","Wegen des Calciumgehalts nicht über dasselbe Infusionsbesteck wie citrathaltige Blutkonserven geben (Gerinnselbildung).","Die Präparate unterscheiden sich leicht in Zusammensetzung (Lactat, Acetat, Malat, Magnesium) – Fachinformation des jeweiligen Produkts beachten."],"darreichung":["Infusionslösung (Beutel, Flaschen)"]},"von-willebrand-faktor":{"wirkmechanismus":"Ergänzt den fehlenden oder defekten von-Willebrand-Faktor, damit Blutplättchen an verletzten Gefässwänden haften können. Der von-Willebrand-Faktor vermittelt die Anheftung der Thrombozyten an die Gefässwand (über das Glykoprotein Ib) und deren Verklumpung. Zudem ist er Trägerprotein für Faktor VIII und schützt diesen vor raschem Abbau; nach der Gabe steigt daher auch der Faktor-VIII-Spiegel, bei rekombinantem von-Willebrand-Faktor ohne Faktor VIII allerdings erst verzögert über einige Stunden.","nebenwirkungen":{"haeufig":["Schwindel, Geschmacksstörungen, Übelkeit (beim rekombinanten Präparat)"],"unbekannt":["Allergische Reaktionen bis zum anaphylaktischen Schock (schwere allergische Reaktion)","Thromboembolische Ereignisse (Thrombose, Lungenembolie)","Hemmkörperbildung gegen von-Willebrand-Faktor oder Faktor VIII","Fieber","Hautausschlag, Nesselsucht, Juckreiz","Herzrasen, Hitzewallungen"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden; kontrollierte Studien fehlen. Beim von-Willebrand-Syndrom wird die Behandlung rund um die Geburt mit dem spezialisierten Zentrum geplant.","stillzeit":"Nur bei klarer Notwendigkeit anwenden; Daten fehlen.","hinweise":["Wird in die Vene gespritzt; Dosierung und Kontrollen (von-Willebrand-Faktor- und Faktor-VIII-Aktivität) durch ein Hämophilie-Zentrum.","Bei Zeichen einer Thrombose (Beinschwellung, Brustschmerz, Atemnot) oder Allergie sofort ärztliche Hilfe holen.","Präparate aus menschlichem Plasma: Chargennummer dokumentieren."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"vorasidenib":{"wirkmechanismus":"Hemmt die veränderten Enzyme IDH1 und IDH2, die in bestimmten Hirntumoren den krebsfördernden Stoff 2-Hydroxyglutarat (2-HG) bilden. Vorasidenib gelangt gut ins Gehirn und senkt dort die 2-HG-Konzentration im Tumorgewebe. Dadurch werden die durch 2-HG verursachten epigenetischen Veränderungen rückgängig gemacht und das Tumorwachstum gebremst.","nebenwirkungen":{"sehrHaeufig":["Erhöhte Leberwerte (ALT, AST, GGT)","Müdigkeit","Kopfschmerzen","Durchfall, Übelkeit","Muskel- und Gelenkschmerzen"],"unbekannt":["Schwere Leberschädigung (Hepatitis, Leberversagen)"]},"schwangerschaft":"Nicht anwenden – im Tierversuch fruchtschädigend. Frauen und Männer verhüten während und bis 3 Monate nach der letzten Dosis; da hormonale Verhütung unwirksam sein kann, eine nicht-hormonale Methode verwenden.","stillzeit":"Während der Behandlung und bis 2 Monate nach der letzten Dosis nicht stillen.","hinweise":["Einmal täglich auf nüchternen Magen einnehmen; Tablette ganz schlucken.","Leberwerte regelmässig kontrollieren lassen; Gelbfärbung von Haut oder Augen, dunklen Urin oder Oberbauchschmerzen sofort melden.","Rauchen kann die Wirkung vermindern."],"darreichung":["Filmtabletten"]},"voriconazol":{"wirkmechanismus":"Hemmt die Bildung eines wichtigen Bausteins der Pilzzellwand und bringt so das Pilzwachstum zum Stillstand. Voriconazol blockiert die pilzeigene Lanosterol-14α-Demethylase, sodass kein Ergosterol mehr für die Zellmembran entsteht; gegen Aspergillus wirkt es abtötend. Es wird über CYP2C19, CYP2C9 und CYP3A4 abgebaut und hemmt diese Enzyme gleichzeitig – die Spiegel schwanken je nach Erbanlage stark und werden deshalb oft gemessen.","nebenwirkungen":{"sehrHaeufig":["Sehstörungen (verschwommenes oder verändertes Sehen, Farbsehstörungen, Lichtscheu)","Kopfschmerzen","Periphere Ödeme (Wassereinlagerungen)","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Abnorme Leberwerte","Hautausschlag","Atemnot","Fieber"],"haeufig":["Agranulozytose, Panzytopenie, Thrombozytopenie, Leukopenie, Anämie","Hypoglykämie, Hypokaliämie, Hyponatriämie","Depression, Halluzinationen, Angst, Schlaflosigkeit, Verwirrtheit","Krampfanfälle, Ohnmacht, Zittern, Schwindel, Kribbeln","Netzhautblutung","Herzrhythmusstörungen, tiefer Blutdruck, Venenentzündung","Gelbsucht, Hepatitis","Akutes Nierenversagen","Haarausfall, Juckreiz, Hautrötung, schuppende Hautentzündung"],"gelegentlich":["Knochenmarkversagen","Nebenniereninsuffizienz, Schilddrüsenunterfunktion","Hirnödem, Enzephalopathie, periphere Neuropathie, Geschmacksstörungen","Sehnerverkrankungen, Doppelbilder","Kammerflimmern, ventrikuläre Tachykardie, QT-Verlängerung","Pankreatitis","Leberversagen","Stevens-Johnson-Syndrom","Phototoxische Hautreaktionen (Lichtempfindlichkeit)"],"selten":["Torsade de pointes, kompletter AV-Block","Toxische epidermale Nekrolyse, DRESS, Angioödem","Anaphylaktoide Reaktionen","Schilddrüsenüberfunktion"],"unbekannt":["Plattenepithelkarzinom der Haut (bei Langzeitbehandlung)","Kutaner Lupus erythematodes","Periostitis (Knochenhautentzündung)"]},"schwangerschaft":"Nicht anwenden, ausser der Nutzen überwiegt eindeutig das Risiko (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter müssen wirksam verhüten.","stillzeit":"Mit Beginn der Behandlung abstillen.","hinweise":["Tabletten mindestens 1 Stunde vor oder 1 Stunde nach einer Mahlzeit einnehmen.","Direktes Sonnenlicht meiden, Sonnenschutz mit hohem Schutzfaktor und schützende Kleidung verwenden; Hautveränderungen ärztlich zeigen.","Sehstörungen sind häufig – bei Sehstörungen nicht Auto fahren und nachts nicht fahren.","Leberwerte, Nierenwerte und Elektrolyte werden regelmässig kontrolliert; oft wird der Voriconazol-Spiegel gemessen."],"darreichung":["Filmtabletten","Pulver für Suspension zum Einnehmen","Pulver zur Herstellung einer Infusionslösung"]},"vortioxetin":{"wirkmechanismus":"Hellt die Stimmung auf, indem es das Serotoninsystem im Gehirn auf mehreren Wegen beeinflusst. Vortioxetin hemmt den Serotonin-Transporter und wirkt zusätzlich direkt an Serotoninrezeptoren: Es blockiert 5-HT3-, 5-HT7- und 5-HT1D-Rezeptoren, ist Partialagonist an 5-HT1B- und Agonist an 5-HT1A-Rezeptoren. Dadurch werden in bestimmten Hirnregionen auch Noradrenalin, Dopamin, Acetylcholin und Histamin beeinflusst. Abgebaut wird es vor allem über CYP2D6.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Abnorme Träume","Schwindel","Durchfall, Verstopfung, Erbrechen","Dyspepsie (Verdauungsbeschwerden)","Juckreiz"],"gelegentlich":["Zähneknirschen (Bruxismus)","Verschwommenes Sehen","Hitzewallungen (Flush)","Nächtliches Schwitzen"],"selten":["Pupillenerweiterung (Mydriasis)"],"unbekannt":["Hyponatriämie (Natriummangel)","Serotoninsyndrom","Blutungen (Blutergüsse, Nasenbluten, Magen-Darm-Blutungen)","Anaphylaxie, Angioödem, Nesselsucht, Hautausschlag","Schlaflosigkeit, Unruhe, Aggressivität","Akathisie (Bewegungsunruhe), Kopfschmerzen","Erhöhtes Prolaktin, Milchfluss (Galaktorrhö)","Suizidgedanken und suizidales Verhalten"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung (begrenzte Daten). Bei Einnahme bis zur Geburt sind beim Neugeborenen Anpassungsstörungen möglich.","stillzeit":"Geht vermutlich in die Muttermilch über; über Abstillen oder Behandlungsverzicht ärztlich entscheiden.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten einnehmen; Übelkeit tritt vor allem zu Beginn auf und klingt meist ab.","Die Wirkung setzt nach etwa 2 Wochen ein; nach Besserung die Behandlung mindestens 6 Monate fortführen.","Absetzen nur in Absprache mit der Ärztin oder dem Arzt.","Schwindel kann die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"vosoritid":{"wirkmechanismus":"Fördert das Längenwachstum der Knochen. Vosoritid ist ein abgewandeltes C-Typ natriuretisches Peptid (CNP), das an den Natriuretischen-Peptid-Rezeptor B (NPR-B) bindet. Bei Achondroplasie bremst ein überaktiver FGFR3-Rezeptor die Knorpelzellen der Wachstumsfugen; Vosoritid hemmt den nachgeschalteten MAPK-Signalweg und fördert so Vermehrung und Reifung der Knorpelzellen und damit das Knochenwachstum.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Rötung, Schwellung, Nesselsucht, Schmerz, Bluterguss)","Erbrechen","Blutdruckabfall (Hypotonie)"],"haeufig":["Übelkeit","Schwindel","Ohnmacht (Synkope) oder Beinahe-Ohnmacht","Müdigkeit","Erhöhte alkalische Phosphatase im Blut"]},"schwangerschaft":"Keine Daten; Anwendung in der Schwangerschaft nicht empfohlen.","stillzeit":"Keine Daten; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Etwa 30 Minuten vor der Injektion soll das Kind etwas essen und ein Glas Flüssigkeit trinken (vermindert Blutdruckabfall und Schwindel).","Täglich etwa zur gleichen Zeit spritzen und die Einstichstelle wechseln.","Wachstum und Wachstumsfugen werden regelmässig ärztlich kontrolliert."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung (subkutan)"]},"vutrisiran":{"wirkmechanismus":"Hemmt in der Leber die Bildung des Eiweisses Transthyretin, das bei der Amyloidose fehlgefaltet in Nerven und Herz abgelagert wird. Vutrisiran ist eine chemisch stabilisierte kleine interferierende RNA (siRNA), die an N-Acetylgalactosamin (GalNAc) gekoppelt ist und dadurch gezielt in Leberzellen aufgenommen wird. Dort führt sie über RNA-Interferenz zum Abbau der Boten-RNA von normalem und mutiertem Transthyretin. Der Transthyretin-Spiegel sinkt stark, ebenso der von Transthyretin abhängige Vitamin-A-Spiegel im Blut.","nebenwirkungen":{"sehrHaeufig":["Schmerzen in Armen oder Beinen","Gelenkschmerzen (Arthralgie)"],"haeufig":["Atemnot (Dyspnoe)","Reaktionen an der Injektionsstelle (Rötung, Schmerz, Juckreiz, Bluterguss)","Erhöhte alkalische Phosphatase im Blut"]},"schwangerschaft":"Nicht empfohlen. Sowohl ein zu tiefer als auch ein zu hoher Vitamin-A-Spiegel kann dem ungeborenen Kind schaden; vor Behandlungsbeginn Schwangerschaft ausschliessen.","stillzeit":"Nicht bekannt, ob Vutrisiran in die Muttermilch übergeht; Stillen nur nach ärztlicher Abwägung.","hinweise":["Wird alle 3 Monate von einer medizinischen Fachperson unter die Haut gespritzt.","Täglich Vitamin A in der empfohlenen Menge ergänzen.","Augenbeschwerden wie Nachtblindheit oder trockene Augen ärztlich melden."],"darreichung":["Injektionslösung in einer Fertigspritze"]}});
